import { useState } from "react"


export default function TodoForm(){
const [todoText, setTodoText] = useState('');

    return<>
    <div>
        <form>
            <textarea
             value={todoText}
             onChange={(e)=>{
                setTodoText(e.target.value)
             }}
            ></textarea>
            <button>Save</button>
        </form>
    </div>
    </>
}
